using System;using System.Linq;using System.IO;using UnityEngine;using UnityEditor;using RoadGunner;using RoadGunner.Editor;
public static class WastelandAudit {
 public static string Main(){var l=RoadGunnerLevelAuthoring.Current;var lines=RoadGunnerLevelAuthoring.Validate(l).Select(x=>x.type+": "+x.text).ToList();var ts=l.gameObject.scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();int missing=ts.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));int badMeshes=ts.SelectMany(t=>t.GetComponents<MeshFilter>()).Count(f=>!f.sharedMesh);int badMats=ts.SelectMany(t=>t.GetComponents<Renderer>()).Count(r=>r.sharedMaterials.Any(m=>!m));int badCols=ts.SelectMany(t=>t.GetComponents<MeshCollider>()).Count(c=>!c.sharedMesh);lines.Add("Missing scripts="+missing+", missing mesh filters="+badMeshes+", missing renderer materials="+badMats+", missing collision meshes="+badCols);lines.Add("Ground mesh matches collision="+(l.ground.sharedMesh==l.ground.GetComponent<MeshCollider>().sharedMesh));lines.Add("Ground bounds="+l.ground.GetComponent<Renderer>().bounds+"; local mesh="+l.ground.sharedMesh.bounds);lines.Add("Authoring root scale="+l.transform.lossyScale+"; player scale="+l.session.vehicle.transform.lossyScale);lines.Add("Game camera="+l.session.follow.GetComponent<Camera>().orthographicSize+"; rotation="+l.session.follow.transform.rotation.eulerAngles+"; FollowCamera retained without bound system");lines.Add("Scene="+l.gameObject.scene.path+"; dirty="+l.gameObject.scene.isDirty+"; navigation needs bake="+l.navigationNeedsBake);var workshop=UnityEngine.Object.FindAnyObjectByType<RepairWorkshop>();lines.Add("Workshop="+workshop.transform.position+"; radius="+workshop.healingRadius+"; max health fraction per second="+workshop.maximumHealthFractionPerSecond+"; wired="+(workshop.session==l.session&&workshop.activeRepairEffect&&workshop.repairingLabel&&workshop.radiusMarking));var old=ts.SelectMany(t=>t.GetComponents<GreenwoodSanctuary>()).Count();lines.Add("Old fountain components="+old);string result=string.Join("\n",lines);File.WriteAllText("Documentation/RoadGunner/Wasteland-Restore-2026-10-10/FinalAudit.txt",result);return result;}
}
